using System.Collections;
using System.Reflection;
using System.Text.Json;
using KsaScripting.Core.Snapshots;

namespace KsaScripting.Core.Api;

/// <summary>
///     The read-only data classes (<c>EngineInfo</c>, <c>OrbitInfo</c>, <c>BodyInfo</c>, ...), generated by
///     reflection over the snapshot records so they can never drift from the data the host returns.
/// </summary>
internal static class ReflectedClasses
{
    private const string SnapshotSuffix = "Snapshot";

    /// <summary>The root records, in documentation order, with their class documentation.</summary>
    private static readonly (Type Record, string Doc)[] Roots =
    [
        (typeof(EngineSnapshot), "One engine's state."),
        (typeof(TankSnapshot), "One propellant tank's contents."),
        (typeof(RcsSnapshot), "One RCS thruster controller's state."),
        (typeof(SolarSnapshot), "One solar panel's state."),
        (typeof(GeneratorSnapshot), "One power generator's state."),
        (typeof(LightSnapshot), "One light's state."),
        (typeof(DockingSnapshot), "One docking port's state."),
        (typeof(DecouplerSnapshot), "One decoupler's state."),
        (typeof(SrbSnapshot), "One solid rocket booster's state, including its internal ballistics."),
        (typeof(EncounterSnapshot), "A predicted encounter with another body."),
        (typeof(PartSnapshot), "One part on a vessel."),
        (typeof(SubpartSnapshot), "One subpart of a part."),
        (typeof(AnimationSnapshot), "One part animation's state."),
        (typeof(OrbitSnapshot), "Orbital elements and event times."),
        (typeof(NavballSnapshot), "Navball readouts."),
        (typeof(EnvironmentSnapshot), "Atmosphere and acceleration readouts at the vessel."),
        (typeof(BodySnapshot), "A celestial body (star, planet or moon)."),
        (typeof(AtmosphereSnapshot), "A body's atmosphere."),
        (typeof(OceanSnapshot), "A body's ocean."),
    ];

    internal static IReadOnlyList<ApiClass> Create()
    {
        var nullability = new NullabilityInfoContext();
        var documented = new Dictionary<Type, string>();
        var queue = new Queue<Type>();
        foreach (var (record, doc) in Roots)
        {
            documented[record] = doc;
            queue.Enqueue(record);
        }

        var seen = new HashSet<Type>(queue);
        var classes = new List<ApiClass>();
        while (queue.Count > 0)
        {
            var record = queue.Dequeue();
            var members = new List<ApiMember>();
            foreach (var property in record.GetProperties(BindingFlags.Public | BindingFlags.Instance))
            {
                if (!property.CanRead || property.GetIndexParameters().Length != 0)
                    continue;

                var type = MapProperty(property, nullability, found =>
                {
                    if (seen.Add(found))
                        queue.Enqueue(found);
                });
                var name = JsonNamingPolicy.CamelCase.ConvertName(property.Name);
                members.Add(Dsl.View(name, type, ReflectedDocs.For(record.Name, property.Name)));
            }

            var doc = documented.TryGetValue(record, out var text)
                ? text
                : $"Data from the game's {record.Name} record.";
            classes.Add(new ApiClass(InfoName(record), doc + $" Read-only data reflected from the game's {record.Name} record.", members));
        }

        return classes;
    }

    private static string InfoName(Type record)
        => record.Name.EndsWith(SnapshotSuffix, StringComparison.Ordinal)
            ? record.Name[..^SnapshotSuffix.Length] + "Info"
            : record.Name + "Info";

    private static ApiType MapProperty(PropertyInfo property, NullabilityInfoContext nullability, Action<Type> discovered)
    {
        var underlying = Nullable.GetUnderlyingType(property.PropertyType);
        var nullable = underlying is not null
                       || (!property.PropertyType.IsValueType
                           && nullability.Create(property).ReadState == NullabilityState.Nullable);
        var mapped = MapType(underlying ?? property.PropertyType, discovered);
        return nullable ? Ty.Nullable(mapped) : mapped;
    }

    private static ApiType MapType(Type type, Action<Type> discovered)
    {
        if (type == typeof(bool))
            return Ty.Boolean;
        if (type == typeof(string) || type.IsEnum)
            return Ty.String;
        if (type == typeof(double3Snap))
            return Ty.Ref("Vec3");
        if (type == typeof(QuatSnap))
            return Ty.Ref("Quat");
        if (IsNumeric(type))
            return Ty.Number;
        if (type.IsArray)
            return Ty.Array(MapType(type.GetElementType()!, discovered));

        var dictionary = FindGeneric(type, typeof(IReadOnlyDictionary<,>)) ?? FindGeneric(type, typeof(IDictionary<,>));
        if (dictionary is not null && dictionary.GetGenericArguments()[0] == typeof(string))
        {
            var value = MapType(dictionary.GetGenericArguments()[1], discovered);
            return new ApiType($"Record<string, {value.TsType}>", $"table<string, {value.LuaType}>");
        }

        var enumerable = FindGeneric(type, typeof(IEnumerable<>));
        if (enumerable is not null && type != typeof(string))
            return Ty.Array(MapType(enumerable.GetGenericArguments()[0], discovered));

        if (type.Name.EndsWith(SnapshotSuffix, StringComparison.Ordinal) && type.Namespace == typeof(EngineSnapshot).Namespace)
        {
            discovered(type);
            return Ty.Ref(InfoName(type));
        }

        return Ty.Unknown;
    }

    private static bool IsNumeric(Type type)
        => Type.GetTypeCode(type) is TypeCode.Byte or TypeCode.SByte or TypeCode.Int16 or TypeCode.UInt16
            or TypeCode.Int32 or TypeCode.UInt32 or TypeCode.Int64 or TypeCode.UInt64
            or TypeCode.Single or TypeCode.Double or TypeCode.Decimal;

    /// <summary>The constructed interface of <paramref name="type"/> (or <paramref name="type"/> itself) matching a generic definition.</summary>
    private static Type? FindGeneric(Type type, Type definition)
    {
        if (type.IsGenericType && type.GetGenericTypeDefinition() == definition)
            return type;
        return type.GetInterfaces().FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == definition);
    }
}
